-- Make an existing login a site admin.
-- First create the user in Authentication -> Users -> Add user (tick "Auto Confirm User"),
-- then this gives that email access to the editor.
insert into public.aits_site_admins (user_id, email)
select id, email from auth.users where email = 'reesha.chhajed.ai@gmail.com'
on conflict (user_id) do nothing;
